import{_ as a,o as l,c as s,a5 as p}from"./chunks/framework.BpTTz2lG.js";const F=JSON.parse('{"title":"编程认知","description":"","frontmatter":{},"headers":[],"relativePath":"program-learn/kernel/program-cognition.md","filePath":"program-learn/kernel/program-cognition.md","lastUpdated":1792848886000}'),e={name:"program-learn/kernel/program-cognition.md"};function t(h,i,n,r,k,o){return l(),s("div",null,[...i[0]||(i[0]=[p(`<h1 id="编程认知" tabindex="-1">编程认知 <a class="header-anchor" href="#编程认知" aria-label="Permalink to &quot;编程认知&quot;">​</a></h1><p>文/晨风不可依米</p><br><h2 id="编程世界" tabindex="-1">编程世界 <a class="header-anchor" href="#编程世界" aria-label="Permalink to &quot;编程世界&quot;">​</a></h2><p>万物皆对象，描述现实事物与抽象概括的映射关系。</p><p>本质上是现实事物所具有的特点和运动，可归结为抽象事物的属性和行为。</p><p>比如，一个人类具有身高、体重、性别、年龄等特点，同时也具有行走、吃饭、睡觉等行为。</p><p>以上这些特点和行为，就是人类所具有属性和行为的抽象概括。</p><h2 id="编程本质" tabindex="-1">编程本质 <a class="header-anchor" href="#编程本质" aria-label="Permalink to &quot;编程本质&quot;">​</a></h2><p>编程的本质是数据和函数的组合。</p><p>数据是现实世界中事物的抽象概括和映射，可通过现实事物理解数据模型。</p><p>函数则是对行为流程的逻辑判断和数据运算；可通过输入参数、逻辑判断和数据运算，以及返回结果来理解函数的流程内容。</p><h2 id="编程思维" tabindex="-1">编程思维 <a class="header-anchor" href="#编程思维" aria-label="Permalink to &quot;编程思维&quot;">​</a></h2><ul><li><p>分解思维: 将整体问题分解为多个小问题，逐步解决。</p></li><li><p>抽象思维: 忽略细节，保留核心特征，抽象概括问题。</p></li><li><p>对象思维: 编排具体特征、行为，以构造描述数据模型。</p></li><li><p>模式识别: 重复结构，统一处理，可提取为逻辑函数。</p></li><li><p>算法思维: 通过有限步骤逻辑判断和数据运算，简洁快速解决问题。</p></li></ul><h2 id="编程概念" tabindex="-1">编程概念 <a class="header-anchor" href="#编程概念" aria-label="Permalink to &quot;编程概念&quot;">​</a></h2><ul><li><p>主线任务: 软件服务产品是围绕<code>用户活动切身想要完成的事物(价值类型: 功能实用和精神消耗)</code>而进行的。</p><ul><li><p>功能实用：完成主线任务所提效的必要工具（省时省力省钱方便）。</p></li><li><p>精神消耗：完成主线任务所满足的情感表达（大多体现在分享欲）。</p></li></ul></li><li><p>用户需求：围绕在主线任务过程中所产生的必要条件（诉求、期待、满足感）。</p></li><li><p>市场痛点：围绕在主线任务过程中所遭遇的过程难题（问题、障碍、关卡点）。</p></li><li><p>理解业务：基于用户需求和市场痛点，通过建立一套“业务目标、业务规则、业务流程”方案，以帮助用户完成主线任务。而业务的核心，在于业务目标所决定的一系列业务规则；而这些规则通常通过生命周期状态，来明确在不同阶段能做什么、不能做什么，从而界定业务的目标与边界。</p></li><li><p>理解技术：在明确业务目标与业务约束的前提下，围绕业务需求构建可落地的技术解决方案；重点关注技术方案的可行性、以及在性能、稳定性、扩展性和成本等下如何实现。另特别注意，数据结构、常见算法、设计模式是技术实现的底层基础。</p></li></ul><h2 id="开发概念" tabindex="-1">开发概念 <a class="header-anchor" href="#开发概念" aria-label="Permalink to &quot;开发概念&quot;">​</a></h2><h3 id="产品概念" tabindex="-1">产品概念 <a class="header-anchor" href="#产品概念" aria-label="Permalink to &quot;产品概念&quot;">​</a></h3><ul><li><p>基于物理设备类型: PC端、Mobile端、Tablet端等。</p></li><li><p>基于软件运行环境: Web端、H5端、App端、桌面端、小程序端等。</p></li></ul><br><h3 id="岗位概念" tabindex="-1">岗位概念 <a class="header-anchor" href="#岗位概念" aria-label="Permalink to &quot;岗位概念&quot;">​</a></h3><ul><li><p>产品负责人(产品规划): 定产品方向、业务价值与优先级。</p></li><li><p>产品经理(需求分析): 分析用户需求，定义功能、需求和业务规则。</p></li><li><p>业务分析师(业务分析): 梳理业务流程、业务问题、业务目标与解决方案。</p></li><li><p>交互设计师(交互设计): 设计用户操作流程、系统交互方式。</p></li><li><p>UI 设计师(界面设计): 设计页面布局、视觉样式与组件规范。</p></li><li><p>系统架构师(技术设计): 设计系统架构、技术方案、模块边界与技术规范。</p></li><li><p>领域建模专家(领域设计): 梳理领域概念、业务关系、领域模型与领域规则。</p></li><li><p>前端工程师(开发实现): 实现用户界面、交互逻辑与前端功能。</p></li><li><p>后端工程师(开发实现): 实现业务逻辑、接口、数据处理与服务能力。</p></li><li><p>数据架构师(数据设计): 设计数据模型、数据库结构与数据治理方案。</p></li><li><p>测试工程师(测试验证): 验证功能、业务规则、性能及系统质量。</p></li><li><p>运维工程师(部署运维): 管理构建、部署、运行环境、监控与故障处理。</p></li><li><p>项目经理(项目管理): 管理进度、资源、风险与跨团队协作。</p></li><li><p>运营人员(产品运营): 推动产品使用、收集反馈、分析数据并促进增长。</p></li></ul><br><h3 id="开发流程" tabindex="-1">开发流程 <a class="header-anchor" href="#开发流程" aria-label="Permalink to &quot;开发流程&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">业务规划</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 需求分析</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 交互探索</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 领域设计</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 系统架构</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 库表设计</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">→</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 界面交互</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 前后端开发</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 测试验证</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 部署上线</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 运营迭代</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 新一轮</span></span></code></pre></div>`,25)])])}const c=a(e,[["render",t]]);export{F as __pageData,c as default};
